INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Donuts!', 'Super Donuts is a Platformer without a jump button! Taking inspiration from the all time greats in the genre! Collect sweets as you travel around the world of Sweetzerland in search of the Baby Donuts! Try out various power ups including Giant! Super Sprinkles, Sticky, Bounce and more! Over 40 levels of increasing challenge will put your gaming skills to the test! There''s plenty of hidden secrets too! See if you can get 100% Complete to unlock something super special! Keep an eye out for free updates which will add new features and levels in the future.' FROM games WHERE igdb_id = 175412 ON CONFLICT (game_id, language_code) DO NOTHING;
