INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sengoku Night Blood', 'Sengoku Night Blood was a Japanese free-to-play otome game, developed as a collaboration between Marvelous Entertainment, Kadokawa, and Idea Factory''s Otomate. It was released in Japan on May 29, 2017, for Android and iOS devices. A 12-episode anime television series adaptation by Typhoon Graphics aired between October 3 and December 26, 2017. A Nintendo Switch port of the game was planned, but it was announced on October 24, 2019 that the Switch port was cancelled along with the mobile game being discontinued on December 25, 2019.' FROM games WHERE igdb_id = 264834 ON CONFLICT (game_id, language_code) DO NOTHING;
