INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Witches'' Legacy: The Ties That Bind', 'How time flies! It seems like only yesterday that Lynn was just a little girl, but now she''s all grown up and marrying Edward. You couldn''t be happier for your adopted daughter - until you discover that Edward is missing! A mysterious letter promised answers to his past, urging him to return to his birthplace. As a witch hunter, Edward is accustomed to danger... but he may have gotten in over his head this time. You and Lynn rush to follow his trail, unaware that a dark presence is watching you.' FROM games WHERE igdb_id = 140209 ON CONFLICT (game_id, language_code) DO NOTHING;
