INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Y.A.S.G', 'Defend your planet! Y.A.S.G is an old-school arcade shooter, where your goal is to defend your planet from danger. Shoot enemy ships and asteroids that wish to destroy your home. But be aware, that some of them can fight back. If your home is destroyed it''s game over. Get as many points as possible. Beat your records. You can always ask a friend to join you - double the player, double the fun!' FROM games WHERE igdb_id = 84935 ON CONFLICT (game_id, language_code) DO NOTHING;
