INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cognizant Protocol', 'Cognizant Protocol, a text based adventure game that brings player into the struggle of Aldis Farrell, an AI scientist who is unable to free himself from his emergency pod buried under crash landed space station. In this strange planet, Players will encounter bizarre life forms, survive through merciless creatures and endure hostile environments. Navigate through dangers with Espy’s swift movement and fight for your survival with Excav’s laser. Unveil the story and make decisions directly with the keyboard throughout the game with Command Line Interface style gameplay.' FROM games WHERE igdb_id = 51557 ON CONFLICT (game_id, language_code) DO NOTHING;
