INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('archipelago-navigable-vr-comic', 29822, '2017-01-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29il.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lo3nmqb9owuaogpnnxmf.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Archipelago: Navigable VR Comic', 'Archipelago is a navigable VR comic containing 65 characters and 6,787 lines of dialogue. It is intended to be a family-friendly story world, suitable for all ages. It is NOT A GAME. You are placed inside a comic world as multiple stories play out in real-time around you. Unlike other VR story experiences, you are free to move around (including flying) as the story plays out. It would take more than 30 hours to follow every single character from start to finish. Archipelago''s written content is roughly equivalent to a 100 page book.' FROM games WHERE igdb_id = 29822 ON CONFLICT (game_id, language_code) DO NOTHING;
