INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cadenza: Fame, Theft and Murder - Collector''s Edition', 'It''s the height of the Fabulous Fifties in your hometown of Las Vegas, and life is good! Rock n'' roll is king, and you''re the new king of rock n'' roll. You’re on top of the world! But you come tumbling down hard when a stranger crashes your concert and swaps places with you. Trapped in a strange body, wanted for murder, and on the run from the police, you''re in a race against time to get your life back before the clock runs out! Can you reclaim your rock n'' roll throne, or will this be your final encore?' FROM games WHERE igdb_id = 281786 ON CONFLICT (game_id, language_code) DO NOTHING;
