INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Offensive Dimensions', 'Offensive Dimensions is a hardcore, dark themed, retro 2d action game. Currently is in early access phase. The demo version is available for downloading. Please try that first. Also, the content of the demo version is identical to the paid version, for now. I''ll keep updating the Early Access version in the future and the demo version won''t be updated anymore. If you tried the demo version and liked my game, then you can consider purchasing my game.' FROM games WHERE igdb_id = 75782 ON CONFLICT (game_id, language_code) DO NOTHING;
