INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bump+Smack', 'Bump+Smack is an exciting casual game where you bump balls and smack the table to get the highest score. Keep the balls from falling below your board and bump them back up to the goals. Smack the table to give that extra "oomph" to get your balls into the goal. Play challenge mode to unlock challenging trophies or try your hand at continuous mode to see how high your score can get. High scores get featured on the Bump+Smack website.' FROM games WHERE igdb_id = 38762 ON CONFLICT (game_id, language_code) DO NOTHING;
