INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'President Evil', 'My name is Tony Dramp. I am a simple ranger who lives from paycheck to paycheck. One day, I found a book that changed my life. I became president of Amerika! But that book turned out to be an ancient artifact and required payment for its services... Darkness enveloped my house and the forest. Now I need to get to the White House to save the country... That''s my story.' FROM games WHERE igdb_id = 72407 ON CONFLICT (game_id, language_code) DO NOTHING;
