INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CarCollector', '"Car Collector" is a Reaction-Time game that will test your reflexes, you must collect cars as they travel across the screen. Collecting cars gives you money to unlock new ones giving you access to new levels. Cars will be crossing the screen rapidly and you must collect them. You lose life if you click on cars that have not yet been activated OR by letting cars that you own escape.' FROM games WHERE igdb_id = 76252 ON CONFLICT (game_id, language_code) DO NOTHING;
