INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Embers of War', 'Embers of War is a fusion of role-playing, real-time strategy, visceral action, strategic tower defense, and addictive hero management set in an original science fiction universe and packed with all of your favorite flavors including charismatic heroes, ruthless betrayal, and an ancient malevolent evil. The game is designed for both keyboard with mouse and controller configurations.' FROM games WHERE igdb_id = 56608 ON CONFLICT (game_id, language_code) DO NOTHING;
