INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gymnastics Superstar', 'WOW. Your dream has come true. You’ve finally reached the Olympics, and you get to compete against world-class gymnasts to win gold for your country. Train with a famous coach who has helped other Olympic gold medalists reach the top. Perfect your moves and win this year''s major competition! Get ready for a lot of practice and dedication, and even come up with your very own gymnastics routine, choreographed by YOU!' FROM games WHERE igdb_id = 87368 ON CONFLICT (game_id, language_code) DO NOTHING;
