INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rain of Pumpkins', 'This is a first person collector! The game plays like a first person shooter but the purpose is to collect things - namely pumpkins! Set in a town populated by skeletons, your task is to gather pumpkins hurled at the town by the local witch. Deliver them to your local chefs at the mills to make pies and earn points. Perform well and the witch will leave you alone – that''s until the next full moon!' FROM games WHERE igdb_id = 75071 ON CONFLICT (game_id, language_code) DO NOTHING;
