INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ananias Fellowship', 'Explore five different worlds, fight their monstrous inhabitants and try to survive and find an ancient artifact to save the world from destruction. For every game session, the game will create new environments full of challenges and surprises, populated with monsters and ancient magical artifacts. There are nine different player classes, each one designed with a unique playing style. Some of them are combat-focused, others have access to magic spells in 5 different schools of magic while others must rely on their special martial skills to survive.' FROM games WHERE igdb_id = 200083 ON CONFLICT (game_id, language_code) DO NOTHING;
