INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boss Defiance', 'Boss Defiance is an arcade­ action competitive and asymmetric game, with semi­procedural level creation.  One player play as the powerful Boss and must fight his way room by room, facing the other 3 players in a battle arena.  The Boss will have to survive until the end of the dungeon to succeed.' FROM games WHERE igdb_id = 39924 ON CONFLICT (game_id, language_code) DO NOTHING;
