INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure Escape: Hidden Ruins', 'Professor Burns is on the brink of the archaeological breakthrough of a lifetime - discovering the mysterious Kumari civilization which is rumored to have the key to eternal life. His plans are foiled when Larissa, an unscrupulous rival archaeologist, forces her way onto the scene with the help of her armed guards. Will you be able to stop Larissa before she takes the treasures of the Kumari civilization for herself? Team up with a curious cast of characters including Rachel, the daughter of the billionaire who funded the expedition, Tawa, a trusty local guide, and Peter, a tech genius with an unnatural love of drones.' FROM games WHERE igdb_id = 123444 ON CONFLICT (game_id, language_code) DO NOTHING;
