INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Casinopia: The Blackjack', 'Casinopia: The Blackjack is the first of the series of Casinopia that offers you a casual blackjack game in virtual reality world and available on HTC Vive. Sit on a casino table, immerse yourself in beautiful leisure places and enjoy the game! Play against a beautiful, attractive dealer in single-mode or join other players in multiplayer-mode. The game also offers in-app purchases which helps you win and boost your rank to the top. Keep playing and practice your Blackjack strategy to reach the top of the world rankings!' FROM games WHERE igdb_id = 71246 ON CONFLICT (game_id, language_code) DO NOTHING;
