INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dying: Reborn VR', 'In DYING: Reborn VR the player becomes an investigator who, using state-of-the-art VR technology, gets to unravel and investigate the case of Mathew''s lost sister as well as a series of eerie events following it. By immersing oneself in the world of D:R, the player will explore a series of fragments that together form 3 chapters of Mathew''s story. Those hungry for the complete 6 chapter story can check out the PS4 version of D:R.' FROM games WHERE igdb_id = 188144 ON CONFLICT (game_id, language_code) DO NOTHING;
