INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evergrow: Paper Forest', 'Solve puzzles in the handcrafted forests of Evergrow through the eyes of an imaginative child and his parents. Discover their unfolding story told through the child''s ever-changing room. In each puzzle, the player must guide the rabbit to fill all tiles with grass while avoiding obstacles and using special tiles.' FROM games WHERE igdb_id = 200247 ON CONFLICT (game_id, language_code) DO NOTHING;
