INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aftermath Y2K', 'Inspired by such games as Castlevania and Ninja Gaiden; aftermath is a NES styled action platformer. However in Aftermath you play as a dog. You must run, jump, and dodge your way through 8 levels to recover your beloved owner. All the while also trying to fend off thugs, bandits, henchmen, and mutants. Explore the world left behind the destruction brought on by Y2K.' FROM games WHERE igdb_id = 41900 ON CONFLICT (game_id, language_code) DO NOTHING;
