INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cars: Lightning League', 'Feel the thrill of high-octane sport racing in Disney•Pixar’s Cars: Lightning League! Blindsided by a new generation of blazing-fast racers, the legendary Lightning McQueen is suddenly pushed out of the sport he loves. To get back in the game, help train the Piston Cup champ in iconic film locations as he prepares for a speedy comeback in this all-new game inspired by Disney•Pixar’s “Cars 3.” Race fast, race smart, and prove to the world that it’s not over until lightning strikes!' FROM games WHERE igdb_id = 98637 ON CONFLICT (game_id, language_code) DO NOTHING;
