INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gates of Nowhere', 'Gates Of Nowhere is a Fantasy/Horror adventure in Virtual Reality for HTC Vive. You''ll be projected in a fantasy dungeon and start your adventure inside an abandoned dark prison. You don’t know what happend and you must find the way out exploring huge dungeons filled with awful and dangerous enemies, hard puzzles to solve and many different weapons to try. The game is composed by four levels, The Awakening, Through the dark, WaterWorks and At the Gates, providing at least 2 hours and half of amazing VR gameplay.' FROM games WHERE igdb_id = 50892 ON CONFLICT (game_id, language_code) DO NOTHING;
