INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Second Coming', 'Second Coming is a sci-fi cartoon gamebook with turn-based 3D battles (xcom-style). It is a sci-fi adventure where you and your team explore an alien ship and uncovers its secrets. This game will appeal to both gamebook enthusiasts as more traditional gamers - extending the gamebook format with digital effects and narration. The story explores the concept of origin of life and alien civilizations.' FROM games WHERE igdb_id = 32606 ON CONFLICT (game_id, language_code) DO NOTHING;
