INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Town: Shopping Mall', 'Don’t have all your gifts for the holiday season? No need to worry, the My Town : Shopping Mall is now open! Grab your tote bags and visit any one of the many stores for everyone on your list, but don’t forget to also get your photos taken with Santa! Have you been dreaming about a new phone or tablet? Stop by the mobile store! There are clothing stores where you can try on the latest trends, stores for the new babies in your life, and music stores where you can live out your rock star dreams! Have you seen an eye doctor recently? Stop by the glasses store to pick up some fresh new frames! We know all this shopping will make you hungry, so come pick up your favorite meals in our large food court!' FROM games WHERE igdb_id = 88919 ON CONFLICT (game_id, language_code) DO NOTHING;
