INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scary Stranger 3D', 'Prepare yourself for prank games with Scary Stranger 3D and Nick & Tani. If you''re a fan of Scary Teacher and Scary Neighbor games, get ready to face the ultimate challenge with the Scary neighbor in this hair-raising 3D offline scary game experience. Embark on a thrilling journey through a twisted narrative filled with puzzle, pranks, and dark secrets. Play as Nick & Tani and make sure to stop the plans of your scary neighbor with your prank games.' FROM games WHERE igdb_id = 303249 ON CONFLICT (game_id, language_code) DO NOTHING;
