INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RadianVR', 'RadianVR is an old-school puzzle game with a twist. Colors are materials. Matching is based on rotation. Everything is realistic. With a wide range of special effects - such as locking, rainbow blocks and automatic flipping - the depth and difficulty increase as you play. It includes an arcade mode, a more relaxing "infinite" mode, and a puzzle mode with 100 hand-crafted boards to solve in as few moves are possible.' FROM games WHERE igdb_id = 41979 ON CONFLICT (game_id, language_code) DO NOTHING;
