INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Google Cricket', 'Ah, summer: the sound of leather on willow, and the spectacle of cricket ... cricket! As the tournament begins, something buzzes outside. A team of crickets sans tickets have set up their own wickets for a game of pest cricket! As they face their archrivals, the snails, it’s sure to be a match for the centuries. Don’t be fooled by their sluggish looks — these fielders can be fast on their feet!' FROM games WHERE igdb_id = 230854 ON CONFLICT (game_id, language_code) DO NOTHING;
