INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'InMind 2 VR', 'An adventure game about a scientific journey inside the emotions chemistry of human brain. You''ll take part in the process of one teenager named John becoming an adult, and help shape John''s future self, by triggering emotions in key moments of his life. The destiny is in your hands! VR isn''t required.' FROM games WHERE igdb_id = 31466 ON CONFLICT (game_id, language_code) DO NOTHING;
