INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Shelter: Survival', 'Last Shelter: Survival is a massively multiplayer, real-time strategy war game set in a post-apocalyptic world overrun by zombies. Players step into the role of a settlement leader, tasked with building and managing their own empire in the wasteland. Train troops, recruit legendary heroes, and forge alliances as you navigate the never-ending conflict, even as humanity teeters on the brink of extinction. Will you choose diplomacy or aggression? The decision is yours to make.' FROM games WHERE igdb_id = 89754 ON CONFLICT (game_id, language_code) DO NOTHING;
