INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hungry Hearts Diner: A Tale of Star-Crossed Souls', 'A cozy narrative-driven diner sim where you run a small family restaurant on the city’s edge, cooking home-style Japanese dishes like rice balls, dumplings, and tempura. Serve colorful customers, unlock new recipes as you cook, and learn their poignant, interwoven stories through conversations sparked by full bellies, an intimate mix of hands-on cooking mechanics and heartfelt, sometimes bittersweet storytelling.' FROM games WHERE igdb_id = 142131 ON CONFLICT (game_id, language_code) DO NOTHING;
