INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Creepster', 'Travel deep into the depths of an evil dungeon and test your might against countless enemies. Collect multiple types of mana crystals to fire off special magical abilities. Place earth traps, hurl fireballs, unleash the power of the sun, and drown your victims with the oceans might. Fast paced action awaits.' FROM games WHERE igdb_id = 29379 ON CONFLICT (game_id, language_code) DO NOTHING;
