INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JoJo''s Bizarre Adventure: Diamond Records', 'JoJo''s Bizarre Adventure: Diamond Records is a 3D action video game developed and published by Bandai Namco Entertainment for iOS and Android, and was released on February 20, 2017 in Japan. It is based on the JoJo''s Bizarre Adventure anime series, with the main portion of the game consisting of quests based on the series'' story. The player controls assembles teams of JoJo''s Bizarre Adventure characters, and play through the quests with the goal of knocking out enemy characters. The game uses a free-to-play model, with the player acquiring new characters and items through a gasha mechanic.' FROM games WHERE igdb_id = 75966 ON CONFLICT (game_id, language_code) DO NOTHING;
