INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legendary Arcane', 'Legendary Arcane is an indie 4-player local platformer game. 8 unique mages, each with 6 widely different spells, learn and master those to fit your strategy and beat your couch opponents. Easy to play, steep mastering curve. Bump the head of others, run for power-ups, afflict enemies with status ailments, dash to dodge spells & reach further, haunt survivors relentlessly as a ghost. Over 60 arenas and mini-games, solo modes and original soundtrack. Designed for controller pad but keyboard friendly.' FROM games WHERE igdb_id = 75362 ON CONFLICT (game_id, language_code) DO NOTHING;
