INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guitar Band Battle', 'Guitar Band: Rock Battle lets you collect and customize super detailed unique guitars, and start your band in the garage, evolving by doing shows, recording albums, and video clips. Assemble your own band by hiring a bassist, drummer, guitarist, and vocalist, just like in a real band. Play in perfect tempo to become a rock and roll hero and conquer success. And the best part? Guitar Band Battle is completely free to play, with in-game purchases available if you want to enhance your gameplay.' FROM games WHERE igdb_id = 175729 ON CONFLICT (game_id, language_code) DO NOTHING;
