INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Little Princess: Stores', 'My Little Princess Stores is a storytelling digital dollhouse game where every game is a new adventure. Have fun pretend playing in the princess village stores. Get the latest fashion at the Clothing store, dressup, makeup and lots of clothing. Find you new best friend and the local Pets store or simply visit the supermarket for some food and party items. There are lots more shops and locations for you to play and discover in Little Princess Stores.' FROM games WHERE igdb_id = 88958 ON CONFLICT (game_id, language_code) DO NOTHING;
