INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CodyCross: Crossword Puzzles', 'CodyCross is a space-themed crossword puzzle game where players help an alien visitor learn about Earth through themed word challenges. Players solve interconnected puzzles by answering trivia questions across various categories, with each completed board revealing a hidden secret word. The game features daily puzzles, multiple difficulty levels, and different play modes including Today''s Password. A subscription removes ads and unlocks additional content and rewards.' FROM games WHERE igdb_id = 86994 ON CONFLICT (game_id, language_code) DO NOTHING;
