INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vanguard V', 'Vanguard V is a fast-paced flight adventure game, designed for Virtual Reality, with diverse settings including flights through space, Earth’s surface, and the worlds below. You are the sole defender and greatest weapon against the Parasites. The freedom of flight meets action adventure!' FROM games WHERE igdb_id = 38798 ON CONFLICT (game_id, language_code) DO NOTHING;
