INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VR Theme Park Rides', 'VR Theme Park Rides is a fun collection of twelve exciting VR-experiences featuring classic and thrilling theme park rides. Catering to enthusiasts of all experience levels, the collection includes something for everyone. Thrill-seekers will enjoy rides that hurl you through the air, while casual players will enjoy ground-based rides and the creepy castle of terror. Skip the line and step right up! No tickets required!' FROM games WHERE igdb_id = 40860 ON CONFLICT (game_id, language_code) DO NOTHING;
