INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simulator gas station', '★Unusual 2D game is a genre simulator, gives you the opportunity to feel in the role of the main at the gas station. The main thing that will need to do this is to refuel cars, but not only, you need a lot more, for example, to monitor the level of fuel in tanks and order them in time, improve the refueling and build buildings that yield profits and much more★' FROM games WHERE igdb_id = 51414 ON CONFLICT (game_id, language_code) DO NOTHING;
