INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Noblemen: 1896', 'The year is 1896, and war has begun... To your right, Militia are cut down by saber wielding cavalry. In the distance, cannon fire echoes as a lumbering Steam Tank fires its auto cannons. Your Gatling Gun Team unleashes a salvo of fire, cutting down an enemy squad like wheat. Behind you, the drone of your Frigate Class Airship reassures you before unleashing its salvo of supporting fire.' FROM games WHERE igdb_id = 87611 ON CONFLICT (game_id, language_code) DO NOTHING;
