INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Torej: Red Cubes', 'Torej: Red Cubes is a puzzle game where the goal is to build a tower the way it reaches and touches all the red cubes in the polygon without it collapsing and falling of the platform. You can play different styles like building as high as you can or trying to make a stable construction. Every one of them is fine as long as you don''t break your creation.' FROM games WHERE igdb_id = 61611 ON CONFLICT (game_id, language_code) DO NOTHING;
