INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Weave of Heroes - RPG', 'Weave is a humorous RPG with strategic combat and neat graphic novel style graphics dubbed. This pocket sized role playing game features complex counterattack mechanics nested within a purposefully bite sized mission structure tailor made for questing on the go. In this tongue-in-cheek adventure it''s up to players to rescue their sister from an army of goofy monsters while learning new skills and confronting a mysterious foe in the process.' FROM games WHERE igdb_id = 27755 ON CONFLICT (game_id, language_code) DO NOTHING;
