INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strange Memo', 'Strange Memo also known as Strange Fancy in older versions, is a Japanese Yume Nikki Fangame. Strange Memo is a traditional fangame. You start as Maigo. They can travel to the Fantasy World by sleeping on the bed, and the main task is to collect effects scattered in it.' FROM games WHERE igdb_id = 201842 ON CONFLICT (game_id, language_code) DO NOTHING;
