INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sandiego Inc.', 'Sandiego Inc. is an educational geography puzzle video game, inspired by the classic Where in the World Is Carmen Sandiego? Players must use their geographical knowledge to track down a villain who has stolen a priceless artifact and is attempting to escape by flying to different countries worldwide. By deciphering clues left behind, players can predict the villain''s next destination and ultimately catch and arrest them. As the game progresses, the clues become increasingly obscure, challenging players'' geographical skills even further.' FROM games WHERE igdb_id = 98120 ON CONFLICT (game_id, language_code) DO NOTHING;
