INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The One Fork Restaurant', 'A funny game about swapping a fork between patrons in a restaurant! Many people are coming to our restaurant, but unfortunately we only have one fork! So our dear patrons will have to share it... even if they don''t want to! Move the fork from one patron to another by touching them or their tables. The patience of each patron slowly decreases when they are waiting for the fork. Help them to eat their meal before they run out of patience!' FROM games WHERE igdb_id = 175255 ON CONFLICT (game_id, language_code) DO NOTHING;
