INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Citizen Kane of Video Games', 'Memories at once real and imagined! Experience Citizen Kane as never before! From the palatial Xanadu to the deathbed of Charles Foster Kane! Be amazed by a spectacle of sight and sound. Play through Every Single Shot of The Classic Movie! (for 5 minutes) At long last! The Citizen Kane of Video Games!!' FROM games WHERE igdb_id = 225271 ON CONFLICT (game_id, language_code) DO NOTHING;
