INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moose Invasion', 'Moose Invasion is a classic style arcade game in which you take on oversized native Canadian wildlife that use magic crystals to harness the powers of force fields, telekinesis and shooting lasers from their eyes. This is done to prevent their invasion of Earth from the newly colonized Mars, and to discover what secret is hidden below the surface of the used-to-be red planet which is creating an unnatural amount of energy.' FROM games WHERE igdb_id = 75002 ON CONFLICT (game_id, language_code) DO NOTHING;
