INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thing-in-Itself', 'Thing-in-Itself is an interactive short story about the struggles of understanding another human being. Using Immanuel Kant''s concept as a framework, it leads the player through stages of a relationship, exploring how perceptions may clash and surroundings can alter. Thing-in-Itself is not a game in a traditional sense - it doesn''t have win or lose conditions and doesn''t present challenge to the player.' FROM games WHERE igdb_id = 26749 ON CONFLICT (game_id, language_code) DO NOTHING;
