INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '100% Pasukaru Sensei: Perfect Paint Bombers', '100% Pasukaru Sensei: Perfect Paint Bombers is a colorful action game featuring over 180 characters across six continents. Players explore the Pasca world through an Adventure Mode, battling bosses in unique coloring bomb challenges. Defeated bosses can be recruited, each with distinct abilities. The Battle Mode supports up to 4 players in competitive painting battles, where the goal is to cover the most map area with paint bombs. Characters can be enhanced by scanning QR codes from physical toy cards, adding special skills to the gameplay.' FROM games WHERE igdb_id = 55906 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 55906 AND c.slug = 'konami' ON CONFLICT DO NOTHING;
