INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ironclads 2: Boshin War', 'Create your fleet and army, hunt the enemy''s fleet, hide your weak squadrons in protected ports until reinforcements arrive, blockade enemy trade routes, amphibious assaults and harbour sieges, struggle for dominance over the seas in turned-based strategic mode. The real time tactical battle mode allows you to set up battles and squadron groups with their formations and management using realistic ship models and characteristics as well as advanced ballistics and weapon models.' FROM games WHERE igdb_id = 29289 ON CONFLICT (game_id, language_code) DO NOTHING;
