INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Theosis', 'Bad news, you''re dead. The second you wake up, you find yourself surrounded by ghosts who, like you, are waiting for their turn to cross the border between Purgatory and Heaven. Albeit dead, your job now is to uncover the truth about your demise and help human beings on Earth in order to earn Graces.' FROM games WHERE igdb_id = 29882 ON CONFLICT (game_id, language_code) DO NOTHING;
