INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lil Tanks', 'Lil Tanks is an action-packed, side-scrolling shooter that puts you in control of a prototype tank -- defending humanity from the alien scourge known as The Cuur. As Earth''s last hope, you must upgrade your tank with unique power-ups and blast the aliens back to where they came from! Level up by destroying The Cuur and earn powerful permanent upgrades. Unlock multiple tanks by completing objectives and finishing the campaign. The survival of the human race rests in your hands!' FROM games WHERE igdb_id = 28046 ON CONFLICT (game_id, language_code) DO NOTHING;
