INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Complete Me', 'Relax and enjoy Classic Tangrams challenge of fitting wooden pieces into a silhouette shape. Exercise your mind with hundreds of unique hand-crafted puzzles. Great fun for all ages! Complete Me is a simple and addictive puzzle game that involves dragging and rotating wooden pieces from a top tray and fitting them into a silhouette shape at the bottom. Puzzles range in difficulty from Beginner to Advanced and are a great way to train your brain and keep you mentally fit everyday.' FROM games WHERE igdb_id = 108834 ON CONFLICT (game_id, language_code) DO NOTHING;
