INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mount Everest Story', 'Can you get your team to the top of Mount Everest? This amazing Everest mountain climbing simulation game dares you! Battle the cold, the thin atmosphere, the wind and the snow! Do your best to avoid debilitating medical conditions! React to dramatic and dynamic weather conditions! Stay alive in the death zone! The higher you climb Mount Everest, the more points you will score! But keep your team rested and in good health. There are severe penalties for injuries.' FROM games WHERE igdb_id = 174331 ON CONFLICT (game_id, language_code) DO NOTHING;
