INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Or', 'Do not underestimate the apparent simplicity of Or because it will amaze you. In the game there will be pitfalls of every kind! The 3D graphics allows you to see the light from above. This opens up a world of possible combinations. With gameplay based around light, Or is a simplified Puzzle/Arcade game. Play through 10 worlds with progressive difficulty, let the light guide you!' FROM games WHERE igdb_id = 29613 ON CONFLICT (game_id, language_code) DO NOTHING;
