INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('4x4-offroad-racing-nitro', 30983, '2017-03-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29dk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nvmv20mf3vuag6hldwrh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '4x4 Offroad Racing Nitro', 'In "4x4 Offroad Racing Nitro" different courses in the three game modes single race, time trial and competition are waiting for the future race champion, and that is you!!! The rapid offroad races lead you through dusty deserts, slippery ice regions and dense forests during day and night. Talent to drive and maximum ruthlessness facing your opponents guarantee a placement in the front ranks. Several offroad cars can be controlled by mouse, keyboard or joystick.' FROM games WHERE igdb_id = 30983 ON CONFLICT (game_id, language_code) DO NOTHING;
