INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Idol Time PriPara Yume All Star Live!', 'Yume Allstar Live features an all-original storyline inspired from the hit TV series as players get into the new kind of PriPara story with their favorite characters from the TV series such as Yui Yumekawa, Nino Nijiiro, Michiru Koda, Shuka Hanazono, even familiar faces like Laala Manaka, Mirei Minami, Sophy Hojo, and more! You''ll never know who will run into while trying to impress the Paparajuku crowd with a wide array of outfits to collect and win, songs to master, and more, aiming to be recognized by Falala herself!' FROM games WHERE igdb_id = 136938 ON CONFLICT (game_id, language_code) DO NOTHING;
