INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Cursed Revolver', 'The Wild West is plunged into chaos when the land is cursed by an artifact known simply as The Cursed Revolver. Discovered by an unsuspecting cowboy, the revolver becomes bound to him and demands only one thing: payment of life. The cowboy must now face the Deadly Demons of the West if he is to have any hope of breaking the curse.' FROM games WHERE igdb_id = 28237 ON CONFLICT (game_id, language_code) DO NOTHING;
