INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amoreon NightClub', 'The Amoreon NightClub is a single player disco, where you can dance with virtual characters, challenge yourself to gain points by following the dance moves, select songs and add your own music. You can see your own VR body, use your hands and fingers with thumb sticks. All nightclub visuals (lasers, particles, dances) are controlled by the music. Watch yourself dancing on a big screen while cameras rotate around the dance floor.' FROM games WHERE igdb_id = 59241 ON CONFLICT (game_id, language_code) DO NOTHING;
