INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlemals', 'Introducing Battlemals: a two-player game where animals duke it out in epic battles across exotic landscapes. The game is simple: be the last animal standing. Avoid spikes while jumping on the rival’s head to score a victory. Will the penguin beat the camel in the forest? Will the bird prove its power against the pig? Unlock all the animals for the ultimate battle and find out if you have what it takes.' FROM games WHERE igdb_id = 26695 ON CONFLICT (game_id, language_code) DO NOTHING;
