INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warhammer 40,000: Dawn of War III - Collector''s Edition', 'Celebrate the return of Dawn of War with a host of exclusive premium collectibles in the Dawn of War III Collector''s Edition. Including; - Gabriel Angelos''s iconic "Godsplitter Daemon Hammer" replica (14.2" x 4.2") - 3 cloth faction banners on wooden poles with custom artwork and slogans (25" x 15.2") - Premium Disc Book - Official soundtrack with 18 epic tracks composed by Paul-Leonard Morgan - Lenticular Art Card which rotates between the 3 race masks (5.7" x 6.7") - "Master of War" digital content pack (same as pre-order bonus)' FROM games WHERE igdb_id = 27768 ON CONFLICT (game_id, language_code) DO NOTHING;
