INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Subdivision Infinity', 'Subdivision Infinity is an immersive and pulse pounding sci-fi 3D space shooter. Ready your ship and cruise the great expanse of space in over 40 engaging missions in 5 distinct locales. Hunt down and destroy enemy spacecraft, crush capital ships, mine asteroids for rare minerals, and find blueprints to craft amazing new vessels. Subdivision Infinity features stunning graphics and tight spaceship game play. Beyond the story''s main missions, you will have an array of optional goals to keep you cruising, including space exploration, bounty hunting, and mining operations.' FROM games WHERE igdb_id = 87618 ON CONFLICT (game_id, language_code) DO NOTHING;
