INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hippo on Elm Street', 'Baby, it''s cold outside. All you want to do is snuggle up in a warm sock and take a nap. But something seems to be going on in the house, and you''re determined to find out what it is. Hippo on Elm Street is a short, adorable text adventure in the style of the old Infocom games. This game is based in the world of the House Hippo, a PSA by the Concerned Children''s Advertisers.' FROM games WHERE igdb_id = 135325 ON CONFLICT (game_id, language_code) DO NOTHING;
