INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Shooter - Dead City', 'You must become a true zombie shooter if you want to survive, and the good thing is you have unlimited bullets! Choose your weapon, shoot zombies and zombie animals until dawn to stop them from turning you into their meal and prevent the end of the world. Get ready for one of the most epic - shooting games of all times. If you like zombie games you are going to love playing Dead City Island missions. The zombie apocalypse has just begun! Your task will be to shoot off zombie heads, arms and legs, and progress through different levels. As you level up, different and stronger zombies will appear. Upgrade weapons in your arsenal, increase their power, range, and firing rate to take down stronger zombies.' FROM games WHERE igdb_id = 200325 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 200325 AND p.igdb_id = 39 ON CONFLICT DO NOTHING;
