INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armor Clash II', 'Armor Clash II is an old-school RTS game, with classic features like base building, modern armors and navies etc. 2 factions and sub-factions for each one, from high tech stealth destroyers to hardcore battleships. In Skirmishes players build base from the start, while in the Random Generated Mission, fast paced combats start immediately. Local network multiplayers are also available, players can fight each other or co-op against AI.' FROM games WHERE igdb_id = 30338 ON CONFLICT (game_id, language_code) DO NOTHING;
