INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Quick Death', 'A Quick Death is a 2-Player local multiplayer Western Shootout where timing, reflex, and psychology are the name of the game. Featuring over 20 unique stages and over a dozen different obstacles and modifiers, A Quick Death takes a classic video game mechanic and pushes it to its most extreme conclusion.' FROM games WHERE igdb_id = 41973 ON CONFLICT (game_id, language_code) DO NOTHING;
