INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hack''n Stalk 2.0', 'This is a sequel to the game Hack''n Stalk (released and completed earlier in 2017). This new game is an "expanded universe" where you''ll visit the city of Riverside, use your skills and high tech devices to corrupt a strict family into a naughty life style. As the first game, this one mixes elements of visual novels, RPGs, click and point adventures and action minigames.​' FROM games WHERE igdb_id = 129490 ON CONFLICT (game_id, language_code) DO NOTHING;
