INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirt Bike Extreme', 'Take part in extreme motorcycle races across the dangerous and challenging tracks. Dirt Bike Extreme is easy to pick up but hard to master. Race, jump and crash your way and other mad rivals through the amazing tracks as you master the skills and the physics of motocross in this high speed racing adventure. Conquer challenging routes on 23 different runs, discover new bikes and become the best of the best! Features: excellent 3D-graphics, challenging routes, 10 different bikes, two gameplay modes: championship and time trial.' FROM games WHERE igdb_id = 87160 ON CONFLICT (game_id, language_code) DO NOTHING;
