INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blade Runner 2049: Memory Lab', '"In this single-player adventure from the world of Blade Runner 2049, you''ve been transported to the Wallace Corporation''s Memory Lab where an eager Joi-Tech model hologram is ready to scan your mind to reveal the circumstances behind your latest retirement. You''ll travel from the memory lab and into strange and thrilling recreations of the future, complete with fully volumetric characters and interactive elements. Within each scene you''ll use futuristic tools to uncover clues to reveal and evidence to hide. Featuring Oculus Touch support and a sprawling, 360º world, Memory Lab brings the Blade Runner universe to you like never before."' FROM games WHERE igdb_id = 81840 ON CONFLICT (game_id, language_code) DO NOTHING;
