INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solmec: Hollow Planet', 'Solmec: Hollow Planet is an adventure game where you play as Soledad, a lone Solmec warrior exploring an ancient, lost planet. His task is to find a cure for the Rot that is killing the Ankazil – spacefaring beasts that are home to the Solmec. With his newfound companion, Pixano, Soledad must explore Creedor and uncover the truth in this new puzzle platformer.' FROM games WHERE igdb_id = 52070 ON CONFLICT (game_id, language_code) DO NOTHING;
