INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toukiden 2: Free Alliances Version', '"The newest title in the hunting-action series "Toukiden," characteristic for its thrilling Targeted Destruction and a Japanese view of the world, will be available as a free-to-play version. You can enjoy participating in Group Missions online with the Free Alliances Version free of charge. (Some items, for example, must be purchased.) You can also play the game up to and including the middle stages of the first chapter of the retail version''s story free of charge. In addition, not only can you fight together with players of the retail version, but you can import your save data to the retail version as well."' FROM games WHERE igdb_id = 28444 ON CONFLICT (game_id, language_code) DO NOTHING;
