INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AHTS Ship Simulator', 'Captain, command a 3000 ton anchor handling and tug supply (AHTS) vessel and navigate it in high seas to a nearby oil rig. You control it with powerful main engines and side thrusters. Two outside water cannons help against a UFO with a tractor beam and fires that make your mission difficult. Set your weather and make sure not to collide with traffic or the rig. Have fun, Captain' FROM games WHERE igdb_id = 44207 ON CONFLICT (game_id, language_code) DO NOTHING;
