INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bundesfighter 2 Turbo', 'Bundesfighter 2 Turbo is a spoof of Street Fighter 2 released by Bohemian Browser Balett as a satirical take on the German elections (also known as Bundestagswahl) of 2017. The player can choose between Angela Merkel (CDU), Martin Schulz (SPD), Özdehardt (Grüne), Sarah Wagenknecht (Linke), Alexander Gauland (AFD) and Christian Lindner (FDP), all having movesets based on conspirancies, jokes and prejudices surrounding their parties.' FROM games WHERE igdb_id = 246234 ON CONFLICT (game_id, language_code) DO NOTHING;
