INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasy Fairways', 'What if you had to get a hole-in-one on every hole? Fantasy Fairways is a golf game where you design your own path to the hole. Bounce the ball off trampolines, zoom through different power ups, even take it through wormholes -- several gizmos let you express yourself. The game is all about balancing your own creativity and skill. Design the hole of your dreams and carefully aim the perfect ace.' FROM games WHERE igdb_id = 30629 ON CONFLICT (game_id, language_code) DO NOTHING;
