INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deer Hunter Reloaded', 'Deer Hunter is Back! Deer Hunter: Reloaded is a 1st person hunting simulation game based off of the #1 hunting franchise in the World. Deer Hunter will provide an authentic hunting experience for players as they venture to some of the top-rated hunting regions in North America from the plains of West Texas to the rugged terrain of Alaska.' FROM games WHERE igdb_id = 64363 ON CONFLICT (game_id, language_code) DO NOTHING;
