INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Answer', 'You - a writer, tired of living in a big city and all the fuss, which wants to get rid of anxiety, find inner peace and return to this in a long-forgotten home. Locked in his own mind, he becomes the protagonist of his new work, which, according to the story, looking for a way out of this madness ...' FROM games WHERE igdb_id = 30062 ON CONFLICT (game_id, language_code) DO NOTHING;
