INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battles of the Valiant Universe CCG', '“Battles of the Valiant Universe” is a free-to-play collectible card game based on the Valiant Comics universe. Its exclusive game mechanics include real time PvP, combos and power-ups which are making it one of the most exciting online collectible card games yet. By focusing on innovation and user experience, in early game testing sessions Silent Legends is receiving praise from all kinds of players, calling the game experience “pleasantly addictive.”' FROM games WHERE igdb_id = 30663 ON CONFLICT (game_id, language_code) DO NOTHING;
