INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Artificial Superintelligence', 'You’re a startup founder building the world’s first sentient supercomputer! Slide either left or right to train your AI, handle the bizarre requests of Silicon Valley residents, and explore parallel universes. If you can keep your employees, your investors, the government, and the internet from tearing apart the fabric of society, then maybe you''ll actually bring about the Singularity. But you''ll probably just get arrested by the FBI. Or kidnapped by an obsessed superfan. Or consumed by a swarm of nanorobots. ¯\_(ツ)_/¯' FROM games WHERE igdb_id = 174353 ON CONFLICT (game_id, language_code) DO NOTHING;
