INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mirt. Tales of the Cold Land', 'Mirt is a small town, lost somewhere in the northern valleys, welcoming none. Everything is frozen here, even time itself. A newcomer will have difficulties getting used to the snow in the middle of summer, the strange natives, each of whom knows something, though never tells, and most of all — to the story of Mirt, not a long history, but already full of secrets.' FROM games WHERE igdb_id = 36710 ON CONFLICT (game_id, language_code) DO NOTHING;
