INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Sky', 'Red Sky is an FPS game with the same kind of old-school gameplay from the mid-90''s, with 16 tough levels and lots of varied gameplay. The game takes at least two hours to beat, but many more if you aren''t an experienced player, and is running on its own custom 3-D engine.' FROM games WHERE igdb_id = 26804 ON CONFLICT (game_id, language_code) DO NOTHING;
