INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Rakuryuusei: The Shattered Sky', 'Touhou Rakuryuusei ~ The Shattered Sky is a fan-made Touhou Project game made using the Touhou Danmakufu ph3 shooting game engine, programmed by Eredom of Dream Compass with music by Abner and character art by Moonturret. The game was released on 23 June 2017, and features 6 stages and 3 Extra stages. The game features 3 playable characters.' FROM games WHERE igdb_id = 280870 ON CONFLICT (game_id, language_code) DO NOTHING;
