INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'What''s Up by Strawberry Studio', 'What''s Up is a fast card-flipping game in which you race to collect sets of birds first. To set up, shuffle the thirty double-sided cards, then lay them out on the table in a grid. Each card features 1-3 birds in one of four colors - red, green, yellow, purple - with the reverse of the card having either the same number of birds in a different color or the same color of birds in a different number. Thus, each number+color combination appears five times in the deck.' FROM games WHERE igdb_id = 175868 ON CONFLICT (game_id, language_code) DO NOTHING;
